"""build_shape_json.py - writes shape.json for kovalam-reef-india from rectify_result.json + rectify_fit.py (2026-10-10).
Run from this folder: python build_shape_json.py   (needs rectify_result.json from rectify_fit.py)"""
import json, math, os, numpy as np
from shapely.geometry import Polygon
import rectify_fit as R
HERE=os.path.dirname(os.path.abspath(__file__))
res=json.load(open(f'{HERE}/rectify_result.json')); sw={s['H']:s for s in res['H_sweep']}
sel=res['selected']; qs=sel['q']
en_sel=R.unproject(R.POLY,qs); m_sel,t,n,s0=R.canon(en_sel)
def to_frame(en): d=en-s0; return np.c_[d@t,d@n]
def version(H,vid,name,note):
    q=sw[H]['q'] if H in sw else qs; en=R.unproject(R.POLY,q); m=to_frame(en); P=Polygon(m)
    return dict(id=vid,name=name,date='2010-02 to 2011-03 (aerial undated; brochure 2011-03-24)',kind='photo_trace',source_ids=['img1','sat2011'],
        method=f'Strips traced on the oblique ASR aerial; rectified through a camera fitted to the 2011-02-28 satellite swash line; camera height fixed at {H} m (the fit cannot determine it).',
        level='visible outer edge of the sand-container strips in the photo (the whitewater patch at the shore-ward end is included)',
        area_m2=round(P.area),bbox_m=[round(float(np.ptp(m[:,0]))),round(float(np.ptp(m[:,1])))],
        polygons_m=[[[round(float(x),1),round(float(y),1)] for x,y in m]],
        polygons_latlon=[[[round(v,6) for v in R.en2ll(*p)] for p in en]],camera_height_m=H,camera_f_px=round(q[4]),fov_deg=sw[H]['fov_deg'] if H in sw else sel['fov_deg'],
        offshore_nearest_edge_m=round(float(m[:,1].min())),note=note)
versions=[version(60,'photo_trace_H60','Photo trace, camera 60 m (default, 2010-11 aerial)','Camera height 60 m gives a 72 deg lens and an offshore distance consistent with the 90 m of WRL Table 4.2; still an assumption.'),
          version(35,'photo_trace_H35','Photo trace, smallest scale (camera 35 m)','Best-fit camera height of the unconstrained search (rms 2.2 px); 48 deg lens. Smallest plausible footprint.'),
          version(80,'photo_trace_H80','Photo trace, largest scale (camera 80 m)','Matches the WRL 65 m long-shore size and 90 m offshore best but needs a 93 deg lens; largest plausible footprint.')]
poly_m=versions[0]['polygons_m']; P=Polygon(poly_m[0])
sh=dict(slug='kovalam-reef-india',name='Kovalam Reef (Lighthouse Beach, Kerala, India)',status='traced',updated='2026-10-10',
 confidence=dict(level='low',reason='Only one oblique, unscaled photo shows the structure, and the scale (camera height) is not fixed by the picture: footprint 550-1,700 m2 for camera heights 30-80 m. The position is tied to the 2011 satellite swash line (+-15 m) and the long-shore size agrees with the 65 m of a secondary table, but the cross-shore size does not (41 vs 85 m).',
   factors=['single oblique photo, no scale bar, no ground control survey','camera height free: rms 2.2-2.8 px for H 30-80 m','swash line used for the fit differs in date from the photo (2011-02 satellite vs 2010-11 aerial)','left (seaward) end of the strips fades into haze','no as-built drawing or survey found; reef later deflated and sank (not drawn)']),
 design_version=dict(drawn='As-built reef of ASR Ltd, completed late Feb 2010 (4,000 m3 per Mead & Borrero 2011; card 4,800 m3), as seen in the ASR aerial taken between completion and March 2011.',
   why_this_one='It is the only built version; the 2005 Kerala Tourism proposal (500 m long, 200 m offshore, Eve\'s Beach) was never built. The aerial shows it intact, before the 2010-2011 deflation reported by Raised Water Research.',
   alternatives_seen=[dict(what='2005 Kerala Tourism submerged reef proposal at Eve\'s/Hawah Beach (500 m x ~200 m offshore, 3-7 m depth)',source_id='card R5',why_not_used='never built, different beach'),
     dict(what='RWR hand-drawn break line (stepped polyline)',source_id='img2',why_not_used='shows the foam line on a monsoon day, no scale; used only to confirm the stepped/echelon typology'),
     dict(what='Earlier text schematic (07_scale/reefs/kovalam-reef-india.footprint.json: 3 chained 30 m units, 1,083 m2)',source_id='footprint',why_not_used='schematic from text; no image evidence of the unit count')]),
 sources=[dict(id='img1',kind='aerial_photo',title='ASR Ltd aerial of the Kovalam reef from the lighthouse end',url='http://web.archive.org/web/20111106035249/http://www.asrltd.com/media/project-pdf/kovalam-coastal-protection.pdf',source_page='ASR brochure p.1; same photo uncropped in WRL TR 2012/08 Fig 4.5 (registry kovalam-reef-india-img-16)',page_or_figure='brochure p.1 composite, upper left',image_date='2010-02 to 2011-03',credit='ASR Ltd',license='not stated; private research copy',local_file='07_scale/shapes/kovalam-reef-india/src/img1_asr_aerial.png',image_size=[915,735],georef=None,
     scale=dict(px_per_m=None,method='camera model fitted to the 2011 satellite swash line',evidence='see METHOD.md section 3; camera height fixed by assumption',uncertainty_pct=50),pixel_polygons=json.load(open(f'{HERE}/pixel_polys_img1_v2.json')),traced_what='outer edge of the visible sand-container strips incl. the whitewater patch',match_notes='good in photo space (overlays/img1_trace_v2.png); metric scale weak',role='primary'),
   dict(id='img2',kind='aerial_photo',title='RWR Kovalam Outline (monsoon swell, hand-drawn break line)',url='https://raisedwaterresearch.com/wp-content/uploads/2019/12/Kovalam-Outline.jpg',source_page='https://raisedwaterresearch.com/spot/artificial-reef/asia/india/kovalam/',page_or_figure='spot page image',image_date='unknown (before 2019)',credit='Raised Water Research',license='not stated',local_file='07_scale/shapes/kovalam-reef-india/src/img2_rwr_outline.jpg',image_size=[475,305],georef=None,scale=None,pixel_polygons=[],traced_what='nothing traced (break line, no scale)',match_notes='confirms a stepped, echelon-like pattern',role='cross_check'),
   dict(id='sat2011',kind='satellite',title='Esri World Imagery Wayback release 10, z17',url='https://wayback.maptiles.arcgis.com/arcgis/rest/services/World_Imagery/WMTS/1.0.0/default028mm/MapServer/tile/10/{z}/{y}/{x}',source_page='https://livingatlas.arcgis.com/wayback/',page_or_figure='-',image_date='2011-02-28',credit='Esri, Maxar, Earthstar Geographics, GIS User Community',license='Esri terms',local_file='07_scale/shapes/kovalam-reef-india/src/satellite_2014.png',image_size=[507,508],
     georef=dict(provider='Esri World Imagery Wayback',zoom=17,bounds=json.load(open(f'{HERE}/src/satellite_2014.png.geo.json'))['bounds'],tile_template='see url',imagery_date='2011-02-28',attribution='Esri, Maxar, Earthstar Geographics, and the GIS User Community'),scale=dict(px_per_m=round(1/1.18155,3),method='georeferenced',evidence='1.18 m/px at the frame centre (sidecar)',uncertainty_pct=2),pixel_polygons=[],traced_what='reef not visible; swash line (landward edge of surf foam) read for the camera fit',match_notes='',role='context')],
 canonical=dict(frame=f"metres; origin = point of the 2011-02-28 swash line nearest the reef centroid ({res['frame']['origin_latlon'][0]}, {res['frame']['origin_latlon'][1]}); +x along the swash line toward bearing {res['frame']['x_bearing_deg']} deg (SSW); +y offshore toward bearing {res['frame']['y_bearing_deg']} deg (WNW)",derived_from='img1 + sat2011 (camera 60 m)',polygons_m=poly_m,area_m2=round(P.area),
   bbox_m=dict(alongshore=round(float(np.ptp(np.array(poly_m[0])[:,0]))),crossshore=round(float(np.ptp(np.array(poly_m[0])[:,1])))),max_dim_m=round(max(P.minimum_rotated_rectangle.exterior.coords[0:1] and [math.dist(a,b) for a in poly_m[0] for b in poly_m[0]])),
   distance_offshore_m=sel['off_mean'],shore_normal_bearing_deg=res['frame']['y_bearing_deg'],note='distance measured from the 2011 swash line; the pre-reef shoreline lay 10-30 m landward (Mead & Borrero 2011 s.4.1.4)'),
 geo=dict(polygons_latlon=versions[0]['polygons_latlon'],shoreline_bearing_deg=res['frame']['x_bearing_deg'],method='unproject traced pixels through the fitted camera onto the sea plane, local ENU about (8.3885, 76.9745), WGS84',source_id='img1+sat2011',position_uncertainty_m=20,camera_latlon=res['camera_latlon']),
 outline_versions=versions,default_outline='photo_trace_H60',
 versions_info='Three outlines of the same sand-container strips, all traced on the ASR aerial photo (taken between completion in Feb 2010 and March 2011) and placed on the 2011-02-28 satellite frame through a fitted camera. They differ only in the assumed camera height (35, 60, 80 m), which the photo cannot fix, so they show the scale uncertainty. Default 60 m: it reproduces the 90 m offshore distance of the WRL review table with a normal wide-angle lens. No survey or design drawing of the built reef was found.',
 angles=[dict(what='strip direction (top and bottom edge of the fan) vs swash line',deg=round(((res['strip_edges']['top_edge_bearing']+res['strip_edges']['bottom_edge_bearing'])/2-res['strip_edges']['shoreline_tangent_bearing'])),method='rectified edge bearings 230.7 and 237.7 deg vs swash tangent 196.0 deg at camera 60 m; +-15 deg')],
 dimensions_check=[dict(quantity='long-shore length',text_value='65 m',text_ref='WRL TR 2012/08 Table 4.2 p.66 (V-shape max dimension)',drawing_value=f"{sel['along_m']} m",diff_pct=round((sel['along_m']-65)/65*100),comment='H60; H80 gives 64 m'),
   dict(quantity='cross-shore width',text_value='85 m',text_ref='same',drawing_value=f"{sel['cross_m']} m",diff_pct=round((sel['cross_m']-85)/85*100),comment='traced fan is half the table value; the faint seaward end may be longer, or the table includes the design extent. H80 gives 68 m (-20%).'),
   dict(quantity='offshore distance (nearest edge)',text_value='90 m to the undisturbed pre-reef shoreline',text_ref='same',drawing_value=f"{sel['off_min']} m from the 2011 swash line (+10-30 m widening = 75-95 m)",diff_pct=None,comment='consistent, but the 90 m was used to choose H, so this is not an independent check'),
   dict(quantity='volume vs footprint',text_value='4,000 m3 (Mead & Borrero 2011), 4,800 m3 (card)',text_ref='paper s.3.1.7',drawing_value=f"{round(P.area)} m2 footprint",diff_pct=None,comment='would need 3.3 m mean height: the real footprint is probably larger than the traced strips')],
 gemini=dict(values={'size':'95 x 48 m','area':'3,800 / 2,245 m2','crest_depth':'1.6 m','offshore':'150 m'},sources_used=[dict(url='Kerala Harbour Engineering Dept Project Report 2011; Thomas et al. 2012 Performance Assessment of Kovalam Multipurpose Reef',what_gemini_said='crest 1.6 m',our_check='unverifiable',evidence='earlier agents (2026-09-25) found no such documents; not re-fetched here (no network)')],summary='Gemini drew a smooth crescent placed to match its own assumed 150 m offshore (circular); not used.'),
 no_source=None,
 references=[dict(id='R-WRL',citation='Blacka, M.J., Shand, T.D., Carley, J.T., Mariani, A. (2013). A Review of Artificial Reefs for Coastal Protection in NSW. WRL Technical Report 2012/08, UNSW Water Research Laboratory. Table 4.2 p.66, Fig 4.5 p.71.',url='https://doi.org/10.4225/53/58e1dc7368c7a',accessed='2026-10-10 (Lior\'s PDF in papers/)',supports='65 x 85 m, 90 m offshore, depth 1.3-3.7 m, submergence 0.2-3.4 m, tide range ~1 m'),
   dict(id='R-MB',citation='Mead, S. and Borrero, J. (2011). Multi-Purpose Reefs - A Decade of Applications. Coasts & Ports 2011, s.3.1.7, 4.1.4, Fig 7.',url='https://search.informit.org/doi/10.3316/informit.715072832934166',accessed='2026-10-10 (Lior\'s PDF)',supports='4,000 m3, completed late Feb 2010, camera at the lighthouse viewing platform, beach 10-30 m wider'),
   dict(id='R-ASR',citation='ASR Ltd (2011). Multi-Purpose Reef Design and Construction, Kovalam, India (brochure, Wayback capture 2011-11-06).',url='http://web.archive.org/web/20111106035249/http://www.asrltd.com/media/project-pdf/kovalam-coastal-protection.pdf',accessed='2026-09-25',supports='aerial photo (img1), completion Feb 2010')],
 verified_on='2026-10-10',verification=[])
sh['status']='verified'
sh['verification']=[
 dict(check='trace follows the visible strips (photo space)',verdict='approximate',evidence='overlays/img1_trace_v2.png; left end blurred, faint strips right of the whitewater not included'),
 dict(check='camera fit residual',verdict='ok (2.2-2.8 px rms)',evidence='overlays/img1_camera_fit_check.png; swash points vs projected satellite swash line'),
 dict(check='scale determined by the photo',verdict='NO',evidence='rms flat for camera height 30-80 m; footprint 546-1,681 m2 (rectify_result.json H_sweep)'),
 dict(check='sensitivity: horizon row +-6 px; satellite swash line +-10 m',verdict='small',evidence='area 1,177-1,251 m2 (horizon), unchanged (swash shift moves position 3 m only)'),
 dict(check='dimensions vs WRL table',verdict='partial',evidence='long-shore -9%, cross-shore -52% at H60 (-20% at H80)'),
 dict(check='design version/state',verdict='as-built shortly after completion; later deflation not drawn',evidence='RWR/ASR/WRL p.70 (Rendle pers. comm. 2013: damage hampers protection)'),
 dict(check='Gemini sources re-fetched',verdict='not possible (no network)',evidence='earlier agents found them unverifiable')]
json.dump(sh,open(f'{HERE}/shape.json','w'),indent=1)
print({v['id']:(v['area_m2'],v['bbox_m'],v['offshore_nearest_edge_m']) for v in versions}, sh['canonical']['max_dim_m'], sh['angles'][0]['deg'])
